AssistantMessageToolRequest(name='create', tool_call_id='toolu_vrtx_01YWr6GPDi418Ri7GnMkTYcz', arguments={'file_text': ':root {
  --bg: #0b0d10;
  --bg-1: #111418;
  --bg-2: #161a1f;
  --bg-3: #1d222a;
