+  --text: #f1f3f5;
+  --text-2: #c5cbd3;
+  --muted: #8b95a3;
+  --accent: #e8c27a;     /* warm gold */
+  --accent-2: #f0d49a;
+  --accent-ink: #1a1408;
+  --warm: #f08a5d;
+  --cool: #6ea8fe;
+  --green: #7ad6a3;
+  --danger: #ff7a7a;
+  --radius: 14px;
+  --radius-lg: 22px;
+  --shadow-1: 0 1px 0 rgba(255,255,255,0.03) inset, 0 10px 30px rgba(0,0,0,0.35);
+  --shadow-2: 0 20px 60px rgba(0,0,0,0.55);
+  --container: 1200px;
+  --ease: cubic-bezier(0.2, 0.7, 0.2, 1);
+}
+
+* { box-sizing: border-box; }
+html { color-scheme: dark; }
+html, body { margin: 0; padding: 0; }
+
+body {
+  font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
+  background: var(--bg);
+  color: var(--text);
+  line-height: 1.55;
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+}
+
+img, svg { display: block; max-width: 100%; }
+
+a { color: inherit; }
+
+/* Focus */
+:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 3px;
+  border-radius: 4px;
+}
+
+.visually-hidden {
+  position: absolute !important;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden; clip: rect(0,0,0,0);
+  white-space: nowrap; border: 0;
+}
+
+.skip-link {
+  position: absolute;
+  left: 12px;
+  top: -40px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  padding: 8px 14px;
+  border-radius: 8px;
+  font-weight: 600;
+  z-index: 1000;
+  transition: top 120ms var(--ease);
+}
+.skip-link:focus { top: 12px; }
+
+/* ---------- Header ---------- */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: rgba(11, 13, 16, 0.85);
+  backdrop-filter: saturate(160%) blur(14px);
+  -webkit-backdrop-filter: saturate(160%) blur(14px);
+  border-bottom: 1px solid var(--line);
+}
+.topbar {
+  background: linear-gradient(90deg, #1a1d22, #15181d);
+  border-bottom: 1px solid var(--line);
+  text-align: center;
+  font-size: 0.825rem;
+  color: var(--text-2);
+}
+.topbar p { margin: 0; padding: 8px 16px; }
+.header-inner {
+  max-width: var(--container);
+  margin: 0 auto;
+  padding: 14px 24px;
+  display: grid;
+  grid-template-columns: auto 1fr auto;
+  align-items: center;
+  gap: 28px;
+}
+.brand {
+  display: inline-flex;
+  align-items: center;
+  gap: 10px;
+  text-decoration: none;
+  font-family: "Fraunces", Georgia, serif;
+  font-weight: 700;
+  letter-spacing: 0.04em;
+  font-size: 1.35rem;
+}
+.brand-mark {
+  color: var(--accent);
+  font-size: 1.5rem;
+  line-height: 1;
+}
+.primary-nav ul {
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  display: flex;
+  gap: 6px;
+  justify-content: center;
+}
+.primary-nav a {
+  display: inline-block;
+  padding: 8px 14px;
+  text-decoration: none;
+  color: var(--text-2);
+  font-weight: 500;
+  font-size: 0.95rem;
+  border-radius: 999px;
+  transition: background 160ms var(--ease), color 160ms var(--ease);
+}
+.primary-nav a:hover { color: var(--text); background: var(--bg-2); }
+.header-actions {
+  display: flex;
+  gap: 4px;
+  align-items: center;
+}
+.icon-btn {
+  position: relative;
+  width: 40px; height: 40px;
+  display: inline-grid;
+  place-items: center;
+  background: transparent;
+  border: 1px solid transparent;
+  color: var(--text-2);
+  border-radius: 10px;
+  cursor: pointer;
+  transition: background 160ms var(--ease), color 160ms var(--ease), border-color 160ms;
+}
+.icon-btn:hover { background: var(--bg-2); color: var(--text); border-color: var(--line); }
+.cart-badge {
+  position: absolute;
+  top: 4px; right: 4px;
+  min-width: 18px; height: 18px;
+  padding: 0 5px;
+  border-radius: 999px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  font-size: 0.7rem;
+  font-weight: 700;
+  display: inline-grid; place-items: center;
+  line-height: 1;
+  transform: scale(0);
+  transition: transform 200ms var(--ease);
+}
+.cart-badge.is-visible { transform: scale(1); }
+
+.search-panel {
+  border-top: 1px solid var(--line);
+  background: var(--bg-1);
+}
+.search-form {
+  max-width: var(--container);
+  margin: 0 auto;
+  padding: 14px 24px;
+  display: flex;
+  gap: 10px;
+}
+.search-form input {
+  flex: 1;
+  background: var(--bg-2);
+  border: 1px solid var(--line-strong);
+  color: var(--text);
+  padding: 12px 14px;
+  border-radius: 10px;
+  font: inherit;
+}
+.search-form input::placeholder { color: var(--muted); }
+
+/* ---------- Buttons ---------- */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  padding: 12px 20px;
+  border-radius: 10px;
+  font: inherit;
+  font-weight: 600;
+  text-decoration: none;
+  border: 1px solid transparent;
+  cursor: pointer;
+  transition: transform 120ms var(--ease), background 160ms var(--ease), color 160ms var(--ease), border-color 160ms;
+  white-space: nowrap;
+}
+.btn:active { transform: translateY(1px); }
+.btn-primary {
+  background: var(--accent);
+  color: var(--accent-ink);
+}
+.btn-primary:hover { background: var(--accent-2); }
+.btn-ghost {
+  background: transparent;
+  color: var(--text);
+  border-color: var(--line-strong);
+}
+.btn-ghost:hover { background: var(--bg-2); border-color: var(--text-2); }
+
+/* ---------- Section heads / shared ---------- */
+main {
+  max-width: var(--container);
+  margin: 0 auto;
+  padding: 0 24px 80px;
+}
+section { padding: 64px 0; }
+section + section { border-top: 1px solid var(--line); }
+
+.eyebrow {
+  margin: 0 0 8px;
+  text-transform: uppercase;
+  letter-spacing: 0.18em;
+  font-size: 0.72rem;
+  color: var(--accent);
+  font-weight: 600;
+}
+.eyebrow-warm { color: var(--warm); }
+
+.section-head {
+  display: flex;
+  align-items: end;
+  justify-content: space-between;
+  gap: 24px;
+  margin-bottom: 28px;
+  flex-wrap: wrap;
+}
+.section-head h2 {
+  font-family: "Fraunces", Georgia, serif;
+  font-weight: 600;
+  font-size: clamp(1.6rem, 2.6vw, 2.2rem);
+  margin: 0;
+  letter-spacing: -0.01em;
+}
+.link-arrow {
+  color: var(--text-2);
+  text-decoration: none;
+  font-weight: 500;
+  display: inline-flex;
+  gap: 6px;
+  align-items: center;
+}
+.link-arrow:hover { color: var(--accent); }
+
+/* ---------- Hero ---------- */
+.hero { padding-top: 56px; padding-bottom: 80px; }
+.hero-grid {
+  display: grid;
+  grid-template-columns: 1.1fr 0.9fr;
+  gap: 56px;
+  align-items: center;
+}
+.hero-copy h1 {
+  font-family: "Fraunces", Georgia, serif;
+  font-weight: 600;
+  font-size: clamp(2.4rem, 5.5vw, 4.4rem);
+  line-height: 1.02;
+  letter-spacing: -0.02em;
+  margin: 8px 0 18px;
+}
+.hero-copy h1 .accent {
+  color: var(--accent);
+  font-style: italic;
+  font-weight: 400;
+}
+.lede {
+  font-size: 1.05rem;
+  color: var(--text-2);
+  max-width: 52ch;
+  margin: 0 0 28px;
+}
+.hero-cta {
+  display: flex;
+  gap: 12px;
+  flex-wrap: wrap;
+  margin-bottom: 36px;
+}
+.hero-stats {
+  display: grid;
+  grid-template-columns: repeat(3, max-content);
+  gap: 28px;
+  margin: 0;
+  padding: 22px 0 0;
+  border-top: 1px solid var(--line);
+}
+.hero-stats div { display: grid; gap: 4px; }
+.hero-stats dt {
+  font-size: 0.78rem;
+  color: var(--muted);
+  text-transform: uppercase;
+  letter-spacing: 0.12em;
+}
+.hero-stats dd {
+  margin: 0;
+  font-family: "Fraunces", Georgia, serif;
+  font-size: 1.6rem;
+  color: var(--text);
+}
+
+.hero-visual {
+  position: relative;
+  aspect-ratio: 5/6;
+  min-height: 460px;
+}
+.hero-card {
+  position: absolute;
+  background: var(--bg-2);
+  border: 1px solid var(--line);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow-2);
+  overflow: hidden;
+  width: 64%;
+  transition: transform 400ms var(--ease);
+}
+.hero-card:hover { transform: translateY(-4px) scale(1.01); }
+.hero-card-a { top: 0; right: 0; transform: rotate(2deg); }
+.hero-card-b { bottom: 6%; left: 0; transform: rotate(-3deg); width: 56%; }
+.hero-card-c { bottom: 22%; right: 14%; transform: rotate(1deg); width: 46%; }
+.hero-swatch {
+  height: 220px;
+  background: linear-gradient(180deg, #2a2f37, #181c22);
+  position: relative;
+  overflow: hidden;
+}
+.hero-swatch::after {
+  content: "";
+  position: absolute; inset: 0;
+  background:
+    radial-gradient(120% 80% at 50% 0%, rgba(232,194,122,0.18), transparent 60%),
+    radial-gradient(60% 50% at 80% 100%, rgba(110,168,254,0.12), transparent 60%);
+}
+.swatch-a { background: linear-gradient(160deg, #3a2c18, #1a1410); }
+.swatch-a::before {
+  content: "";
+  position: absolute; left: 50%; top: 20%;
+  width: 60px; height: 140px;
+  border-radius: 30px 30px 4px 4px;
+  background: linear-gradient(180deg, #f0d49a 0%, #b8924a 70%, #4a3818 100%);
+  transform: translateX(-50%);
+  box-shadow: 0 0 60px 10px rgba(232,194,122,0.35);
+}
+.swatch-b { background: linear-gradient(160deg, #1f2a2e, #0f1518); }
+.swatch-b::before {
+  content: "";
+  position: absolute; left: 50%; bottom: 20%;
+  width: 110px; height: 90px;
+  border-radius: 50% 50% 14px 14px;
+  background: radial-gradient(circle at 30% 30%, #c9956b, #6b4123 70%, #2c1a0e);
+  transform: translateX(-50%);
+}
+.swatch-c { background: linear-gradient(160deg, #2c2238, #150f1c); }
+.swatch-c::before {
+  content: "";
+  position: absolute; left: 50%; top: 30%;
+  width: 56px; height: 110px;
+  border-radius: 8px;
+  background: linear-gradient(180deg, #d6b3c2, #7a4d63 80%, #2e1a26);
+  transform: translateX(-50%);
+  box-shadow: inset 0 -10px 0 rgba(0,0,0,0.25);
+}
+.hero-meta {
+  display: flex;
+  justify-content: space-between;
+  padding: 14px 16px;
+  font-size: 0.9rem;
+  color: var(--text-2);
+  border-top: 1px solid var(--line);
+}
+
+/* ---------- Categories ---------- */
+.category-grid {
+  list-style: none;
+  margin: 0; padding: 0;
+  display: grid;
+  grid-template-columns: repeat(6, 1fr);
+  gap: 14px;
+}
+.cat {
+  display: grid;
+  place-items: end start;
+  aspect-ratio: 4/5;
+  padding: 16px;
+  border-radius: var(--radius);
+  background: var(--bg-2);
+  border: 1px solid var(--line);
+  text-decoration: none;
+  color: var(--text);
+  font-weight: 600;
+  position: relative;
+  overflow: hidden;
+  transition: transform 200ms var(--ease), border-color 160ms;
+}
+.cat:hover { transform: translateY(-3px); border-color: var(--line-strong); }
+.cat span { position: relative; z-index: 1; font-size: 0.95rem; }
+.cat::before {
+  content: "";
+  position: absolute; inset: 0;
+  background-size: cover;
+  background-position: center;
+  opacity: 0.85;
+  transition: transform 600ms var(--ease), opacity 200ms;
+}
+.cat:hover::before { transform: scale(1.06); opacity: 1; }
+.cat::after {
+  content: "";
+  position: absolute; inset: 0;
+  background: linear-gradient(180deg, rgba(0,0,0,0) 30%, rgba(0,0,0,0.75));
+}
+.cat-1::before { background: radial-gradient(circle at 50% 30%, #d4a35a, #2b1f10 70%); }
+.cat-2::before { background: radial-gradient(circle at 50% 60%, #8a5a3a, #1a120b 70%); }
+.cat-3::before { background: radial-gradient(circle at 50% 50%, #4a5a6a, #14181d 70%); }
+.cat-4::before { background: radial-gradient(circle at 50% 40%, #a3849c, #1d141a 70%); }
+.cat-5::before { background: radial-gradient(circle at 40% 60%, #6a8a6a, #121a14 70%); }
+.cat-6::before { background: radial-gradient(circle at 50% 50%, #6a6a8a, #14141d 70%); }
+
+/* ---------- Filter chips ---------- */
+.filter-bar {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px;
+}
+.chip {
+  background: var(--bg-2);
+  color: var(--text-2);
+  border: 1px solid var(--line);
+  padding: 8px 14px;
+  border-radius: 999px;
+  cursor: pointer;
+  font: inherit;
+  font-size: 0.875rem;
+  transition: background 160ms, color 160ms, border-color 160ms;
+}
+.chip:hover { color: var(--text); border-color: var(--line-strong); }
+.chip.is-active {
+  background: var(--accent);
+  color: var(--accent-ink);
+  border-color: var(--accent);
+}
+
+/* ---------- Product Grid ---------- */
+.product-grid {
+  list-style: none;
+  margin: 0; padding: 0;
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 20px;
+}
+.product {
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: transform 200ms var(--ease), border-color 160ms;
+}
+.product:hover { transform: translateY(-3px); border-color: var(--line-strong); }
+.product-art {
+  aspect-ratio: 1;
+  position: relative;
+  overflow: hidden;
+}
+.product-art::after {
+  content: "";
+  position: absolute; inset: 0;
+  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.45));
+  pointer-events: none;
+}
+.product-tag {
+  position: absolute;
+  top: 12px; left: 12px;
+  background: rgba(11,13,16,0.85);
+  backdrop-filter: blur(8px);
+  color: var(--text);
+  font-size: 0.72rem;
+  font-weight: 600;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  padding: 5px 10px;
+  border-radius: 999px;
+  border: 1px solid var(--line);
+  z-index: 2;
+}
+.product-tag.tag-new { color: var(--green); border-color: rgba(122,214,163,0.3); }
+.product-tag.tag-sale { color: var(--warm); border-color: rgba(240,138,93,0.3); }
+.product-fav {
+  position: absolute;
+  top: 10px; right: 10px;
+  width: 36px; height: 36px;
+  display: inline-grid; place-items: center;
+  background: rgba(11,13,16,0.7);
+  border: 1px solid var(--line);
+  border-radius: 999px;
+  color: var(--text-2);
+  cursor: pointer;
+  z-index: 2;
+  transition: color 160ms, background 160ms;
+}
+.product-fav:hover { color: var(--warm); background: rgba(11,13,16,0.9); }
+.product-fav[aria-pressed="true"] { color: var(--warm); }
+
+.product-body {
+  padding: 16px;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  flex: 1;
+}
+.product-cat {
+  font-size: 0.72rem;
+  text-transform: uppercase;
+  letter-spacing: 0.14em;
+  color: var(--muted);
+  margin: 0;
+}
+.product-title {
+  margin: 0;
+  font-size: 1rem;
+  font-weight: 600;
+  color: var(--text);
+}
+.product-title a {
+  text-decoration: none;
+  color: inherit;
+}
+.product-title a:hover { color: var(--accent); }
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 0.825rem;
+  color: var(--text-2);
+}
+.stars { color: var(--accent); letter-spacing: 1px; }
+.product-foot {
+  margin-top: auto;
+  padding-top: 12px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+}
+.price { display: flex; align-items: baseline; gap: 8px; }
+.price-now { font-weight: 700; font-size: 1.05rem; }
+.price-was {
+  color: var(--muted);
+  text-decoration: line-through;
+  font-size: 0.875rem;
+}
+.add-btn {
+  background: transparent;
+  border: 1px solid var(--line-strong);
+  color: var(--text);
+  padding: 8px 14px;
+  border-radius: 999px;
+  font: inherit;
+  font-size: 0.825rem;
+  font-weight: 600;
+  cursor: pointer;
+  transition: background 160ms, color 160ms, border-color 160ms;
+}
+.add-btn:hover {
+  background: var(--accent);
+  color: var(--accent-ink);
+  border-color: var(--accent);
+}
+
+/* Product art swatches */
+.pa-1 { background: linear-gradient(160deg, #3a2c18, #14100a); }
+.pa-1::before {
+  content: ""; position: absolute; left: 50%; top: 16%; width: 38%; height: 70%;
+  border-radius: 50% 50% 8px 8px;
+  background: linear-gradient(180deg, #f0d49a, #8a6a30 70%, #2e220e);
+  transform: translateX(-50%);
+  box-shadow: 0 0 80px 10px rgba(232,194,122,0.25);
+}
+.pa-2 { background: linear-gradient(160deg, #20272d, #0e1216); }
+.pa-2::before {
+  content: ""; position: absolute; left: 50%; top: 30%; width: 50%; height: 50%;
+  border-radius: 50%;
+  background: radial-gradient(circle at 30% 30%, #c4a07c, #6b4a30 70%, #2e1d0f);
+  transform: translateX(-50%);
+}
+.pa-3 { background: linear-gradient(160deg, #2c2238, #15101c); }
+.pa-3::before {
+  content: ""; position: absolute; left: 50%; top: 22%; width: 28%; height: 60%;
+  border-radius: 6px;
+  background: linear-gradient(180deg, #e0bccc, #6b4258 80%, #281520);
+  transform: translateX(-50%);
+}
+.pa-4 { background: linear-gradient(160deg, #1f2a26, #0d1411); }
+.pa-4::before {
+  content: ""; position: absolute; left: 50%; top: 30%; width: 56%; height: 48%;
+  border-radius: 50%;
+  background: radial-gradient(circle at 35% 30%, #a8c4a0, #4a6a48 70%, #1a2a1a);
+  transform: translateX(-50%);
+}
+.pa-5 { background: linear-gradient(160deg, #2a2018, #14100b); }
+.pa-5::before {
+  content: ""; position: absolute; left: 50%; top: 18%; width: 40%; height: 70%;
+  border-radius: 16px;
+  background: linear-gradient(180deg, #c9885a, #6b3f20 80%, #2a1a0c);
+  transform: translateX(-50%);
+}
+.pa-6 { background: linear-gradient(160deg, #1d2530, #0c1118); }
+.pa-6::before {
+  content: ""; position: absolute; left: 50%; top: 26%; width: 50%; height: 56%;
+  border-radius: 50% 50% 14px 14px;
+  background: linear-gradient(180deg, #a0b4d0, #4a607c 70%, #1a2230);
+  transform: translateX(-50%);
+}
+.pa-7 { background: linear-gradient(160deg, #2a2230, #15101a); }
+.pa-7::before {
+  content: ""; position: absolute; left: 50%; top: 24%; width: 32%; height: 64%;
+  border-radius: 8px 8px 30px 30px;
+  background: linear-gradient(180deg, #b89cc8, #5a3d68 80%, #1f1428);
+  transform: translateX(-50%);
+}
+.pa-8 { background: linear-gradient(160deg, #28201c, #131010); }
+.pa-8::before {
+  content: ""; position: absolute; left: 50%; top: 28%; width: 60%; height: 50%;
+  border-radius: 50%;
+  background: radial-gradient(circle at 30% 30%, #d4a87a, #6b4a30 70%, #2c1d11);
+  transform: translateX(-50%);
+}
+
+/* ---------- Deals ---------- */
+.countdown {
+  display: inline-flex;
+  align-items: baseline;
+  gap: 4px;
+  background: var(--bg-2);
+  border: 1px solid var(--line);
+  padding: 10px 16px;
+  border-radius: 12px;
+  font-variant-numeric: tabular-nums;
+  font-weight: 600;
+  color: var(--text);
+  margin: 0;
+}
+.countdown [data-unit] {
+  font-family: "Fraunces", Georgia, serif;
+  font-size: 1.15rem;
+}
+.cd-sep {
+  color: var(--muted);
+  font-size: 0.72rem;
+  text-transform: uppercase;
+  margin-right: 6px;
+  letter-spacing: 0.06em;
+}
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  grid-auto-rows: 1fr;
+  gap: 18px;
+}
+.deal {
+  position: relative;
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+}
+.deal-feature { grid-row: span 1; flex-direction: row; }
+.deal-feature .deal-art { flex: 1.1; min-height: 320px; }
+.deal-feature .deal-body { flex: 1; }
