// NOVA — home page interactions

const PRODUCTS = [
  {
    id: "halo-floor",
    name: "Halo Floor Lamp",
    category: "lighting",
    categoryLabel: "Lighting",
    price: 320,
    was: null,
    rating: 4.8,
    reviews: 124,
    tag: "new",
    art: "pa-1",
  },
  {
    id: "ember-vessel",
    name: "Ember Vessel — Large",
    category: "ceramics",
    categoryLabel: "Ceramics",
    price: 84,
    was: null,
    rating: 4.9,
    reviews: 88,
    tag: null,
    art: "pa-2",
  },
  {
    id: "no-04",
    name: "No. 04 Eau de Parfum",
    category: "fragrance",
    categoryLabel: "Fragrance",
    price: 140,
    was: null,
    rating: 4.7,
    reviews: 212,
    tag: "new",
    art: "pa-3",
  },
  {
    id: "moss-throw",
    name: "Moss Wool Throw",
    category: "textiles",
    categoryLabel: "Textiles",
    price: 96,
    was: 140,
    rating: 4.6,
    reviews: 64,
    tag: "sale",
    art: "pa-4",
  },
  {
    id: "clay-pendant",
    name: "Clay Pendant Light",
    category: "lighting",
    categoryLabel: "Lighting",
    price: 210,
    was: null,
    rating: 4.8,
    reviews: 47,
    tag: null,
    art: "pa-5",
  },
  {
    id: "tide-bowl",
    name: "Tide Serving Bowl",
    category: "ceramics",
    categoryLabel: "Ceramics",
    price: 64,
    was: 88,
    rating: 4.5,
    reviews: 39,
    tag: "sale",
    art: "pa-6",
  },
  {
    id: "no-07",
    name: "No. 07 Solid Perfume",
    category: "fragrance",
    categoryLabel: "Fragrance",
    price: 58,
    was: null,
    rating: 4.6,
    reviews: 156,
    tag: null,
    art: "pa-7",
  },
  {
    id: "ridge-mug",
    name: "Ridge Stoneware Mug",
    category: "ceramics",
    categoryLabel: "Ceramics",
    price: 28,
    was: null,
    rating: 4.9,
    reviews: 301,
    tag: null,
    art: "pa-8",
  },
];

// ---------- Product grid ----------
const grid = document.getElementById("product-grid");

function starString(rating) {
  const full = Math.round(rating);
  return "★★★★★".slice(0, full) + "☆☆☆☆☆".slice(0, 5 - full);
}

function priceHTML(p) {
  if (p.was) {
    return `<span class="price">
        <span class="price-now">$${p.price}</span>
        <span class="price-was" aria-label="was $${p.was}">$${p.was}</span>
      </span>`;
  }
  return `<span class="price"><span class="price-now">$${p.price}</span></span>`;
}

function tagHTML(tag) {
  if (!tag) return "";
  if (tag === "new") return `<span class="product-tag tag-new">New</span>`;
  if (tag === "sale") return `<span class="product-tag tag-sale">Sale</span>`;
  return `<span class="product-tag">${tag}</span>`;
}

function renderProducts(filter = "all") {
  const items = PRODUCTS.filter(
    (p) => filter === "all" || p.category === filter
  );
  grid.innerHTML = items
    .map(
      (p) => `
    <li class="product" data-id="${p.id}">
      <div class="product-art ${p.art}">
        ${tagHTML(p.tag)}
        <button
          type="button"
          class="product-fav"
          aria-pressed="false"
          aria-label="Save ${p.name} to wishlist"
          data-fav="${p.id}"
        >
          <svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18">
            <path d="M12 20s-7-4.35-7-10a4 4 0 0 1 7-2.65A4 4 0 0 1 19 10c0 5.65-7 10-7 10Z"
              fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/>
          </svg>
        </button>
      </div>
      <div class="product-body">
        <p class="product-cat">${p.categoryLabel}</p>
        <h3 class="product-title"><a href="#">${p.name}</a></h3>
        <p class="product-rating">
          <span class="stars" aria-hidden="true">${starString(p.rating)}</span>
          <span>${p.rating.toFixed(1)} <span class="visually-hidden">out of 5</span> (${p.reviews})</span>
        </p>
        <div class="product-foot">
          ${priceHTML(p)}
          <button
            type="button"
            class="add-btn"
            data-add="${p.id}"
            aria-label="Add ${p.name} to cart"
          >Add</button>
        </div>
      </div>
    </li>
  `
    )
    .join("");
}

renderProducts("all");

// ---------- Filter chips ----------
const chips = document.querySelectorAll(".chip");
chips.forEach((chip) => {
  chip.addEventListener("click", () => {
    chips.forEach((c) => {
      c.classList.remove("is-active");
      c.setAttribute("aria-selected", "false");
    });
    chip.classList.add("is-active");
    chip.setAttribute("aria-selected", "true");
    renderProducts(chip.dataset.filter);
  });
});

// ---------- Cart + Wishlist ----------
let cartCount = 0;
const cartCountEl = document.getElementById("cart-count");
const cartBtn = document.getElementById("cart-btn");

function updateCart(name) {
  cartCount += 1;
  cartCountEl.textContent = String(cartCount);
  cartCountEl.classList.add("is-visible");
  cartBtn.setAttribute(
    "aria-label",
    `Cart, ${cartCount} item${cartCount === 1 ? "" : "s"}`
  );
  showToast(`Added "${name}" to cart`);
}

document.addEventListener("click", (e) => {
  const addBtn = e.target.closest("[data-add]");
  if (addBtn) {
    const id = addBtn.dataset.add;
    const product = PRODUCTS.find((p) => p.id === id);
    if (product) updateCart(product.name);
    return;
  }
  const favBtn = e.target.closest("[data-fav]");
  if (favBtn) {
    const pressed = favBtn.getAttribute("aria-pressed") === "true";
    favBtn.setAttribute("aria-pressed", pressed ? "false" : "true");
    const id = favBtn.dataset.fav;
    const product = PRODUCTS.find((p) => p.id === id);
    if (product && !pressed) showToast(`Saved "${product.name}" to wishlist`);
  }
});

// ---------- Toast (live region) ----------
