  const m = Math.floor(diff / 60000); diff -= m * 60000;
  const s = Math.floor(diff / 1000);
  const units = countdown.querySelectorAll("[data-unit]");
  units[0].textContent = pad(d);
  units[1].textContent = pad(h);
  units[2].textContent = pad(m);
  units[3].textContent = pad(s);
}
tick();
setInterval(tick, 1000);

// ---------- Newsletter ----------
const form = document.getElementById("newsletter-form");
const status = document.getElementById("newsletter-status");
const emailInput = document.getElementById("email");

form.addEventListener("submit", (e) => {
  e.preventDefault();
  status.classList.remove("is-error");
  const value = emailInput.value.trim();
  const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
  if (!valid) {
    status.classList.add("is-error");
    status.textContent = "Please enter a valid email address.";
    emailInput.focus();
    return;
  }
  status.textContent = `Thanks — we'll write to ${value} every other Friday.`;
  form.reset();
});

