  cartCount += 1;
  cartCountEl.textContent = String(cartCount);
  cartCountEl.classList.add("is-visible");
  cartBtn.setAttribute(
    "aria-label",
    `Cart, ${cartCount} item${cartCount === 1 ? "" : "s"}`
  );
